24→function readNonEmptyString(value: unknown): string | null {
25→  return typeof value === "string" && value.trim().length > 0 ? value.trim() : null;
26→}
27→
28→export const sessionCodec: AdapterSessionCodec = {
29→  deserialize(raw: unknown) {
30→    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) return null;
31→    const record = raw as Record<string, unknown>;
32→    const sessionId = readNonEmptyString(record.sessionId) ?? readNonEmptyString(record.session_id);
33→    if (!sessionId) return null;
34→    const cwd =
35→      readNonEmptyString(record.cwd) ??
36→      readNonEmptyString(record.workdir) ??
37→      readNonEmptyString(record.folder);
38→    const workspaceId = readNonEmptyString(record.workspaceId) ?? readNonEmptyString(record.workspace_id);
39→    const repoUrl = readNonEmptyString(record.repoUrl) ?? readNonEmptyString(record.repo_url);
40→    const repoRef = readNonEmptyString(record.repoRef) ?? readNonEmptyString(record.repo_ref);
41→    return {
42→      sessionId,
43→      ...(cwd ? { cwd } : {}),
44→      ...(workspaceId ? { workspaceId } : {}),
45→      ...(repoUrl ? { repoUrl } : {}),
46→      ...(repoRef ? { repoRef } : {}),
47→    };
48→  },
49→  serialize(params: Record<string, unknown> | null) {
50→    if (!params) return null;
51→    const sessionId = readNonEmptyString(params.sessionId) ?? readNonEmptyString(params.session_id);
52→    if (!sessionId) return null;
53→    const cwd =
54→      readNonEmptyString(params.cwd) ??
55→      readNonEmptyString(params.workdir) ??
56→      readNonEmptyString(params.folder);
57→    const workspaceId = readNonEmptyString(params.workspaceId) ?? readNonEmptyString(params.workspace_id);
58→    const repoUrl = readNonEmptyString(params.repoUrl) ?? readNonEmptyString(params.repo_url);
59→    const repoRef = readNonEmptyString(params.repoRef) ?? readNonEmptyString(params.repo_ref);
60→    return {
61→      sessionId,
62→      ...(cwd ? { cwd } : {}),
63→      ...(workspaceId ? { workspaceId } : {}),
64→      ...(repoUrl ? { repoUrl } : {}),
65→      ...(repoRef ? { repoRef } : {}),
66→    };
67→  },
68→  getDisplayId(params: Record<string, unknown> | null) {
69→    if (!params) return null;
70→    return readNonEmptyString(params.sessionId) ?? readNonEmptyString(params.session_id);
71→  },
72→};
