   1→/**
   2→ * JSON-RPC 2.0 message types and protocol helpers for the host ↔ worker IPC
   3→ * channel.
   4→ *
   5→ * The Paperclip plugin runtime uses JSON-RPC 2.0 over stdio to communicate
   6→ * between the host process and each plugin worker process. This module defines:
   7→ *
   8→ * - Core JSON-RPC 2.0 envelope types (request, response, notification, error)
   9→ * - Standard and plugin-specific error codes
  10→ * - Typed method maps for host→worker and worker→host calls
  11→ * - Helper functions for creating well-formed messages
  12→ *
  13→ * @see PLUGIN_SPEC.md §12.1 — Process Model
  14→ * @see PLUGIN_SPEC.md §13 — Host-Worker Protocol
  15→ * @see https://www.jsonrpc.org/specification
  16→ */
  17→
  18→import type {
  19→  PaperclipPluginManifestV1,
  20→  PluginLauncherBounds,
  21→  PluginLauncherRenderContextSnapshot,
  22→  PluginLauncherRenderEnvironment,
  23→  PluginStateScopeKind,
  24→  Company,
  25→  Project,
  26→  Issue,
  27→  IssueComment,
  28→  IssueDocument,
  29→  IssueDocumentSummary,
  30→  Agent,
  31→  Goal,
  32→} from "@paperclipai/shared";
  33→export type { PluginLauncherRenderContextSnapshot } from "@paperclipai/shared";
  34→
  35→import type {
  36→  PluginEvent,
  37→  PluginJobContext,
  38→  PluginWorkspace,
  39→  ToolRunContext,
  40→  ToolResult,
  41→} from "./types.js";
  42→import type {
  43→  PluginHealthDiagnostics,
  44→  PluginConfigValidationResult,
  45→  PluginWebhookInput,
  46→} from "./define-plugin.js";
  47→
  48→// ---------------------------------------------------------------------------
  49→// JSON-RPC 2.0 — Core Protocol Types
  50→// ---------------------------------------------------------------------------
  51→
  52→/** The JSON-RPC protocol version. Always `"2.0"`. */
  53→export const JSONRPC_VERSION = "2.0" as const;
  54→
  55→/**
  56→ * A unique request identifier. JSON-RPC 2.0 allows strings or numbers;
  57→ * we use strings (UUIDs or monotonic counters) for all Paperclip messages.
  58→ */
  59→export type JsonRpcId = string | number;
  60→
  61→/**
  62→ * A JSON-RPC 2.0 request message.
  63→ *
  64→ * The host sends requests to the worker (or vice versa) and expects a
  65→ * matching response with the same `id`.
  66→ */
  67→export interface JsonRpcRequest<
  68→  TMethod extends string = string,
  69→  TParams = unknown,
  70→> {
  71→  readonly jsonrpc: typeof JSONRPC_VERSION;
  72→  /** Unique request identifier. Must be echoed in the response. */
  73→  readonly id: JsonRpcId;
  74→  /** The RPC method name to invoke. */
  75→  readonly method: TMethod;
  76→  /** Structured parameters for the method call. */
  77→  readonly params: TParams;
  78→}
  79→
  80→/**
  81→ * A JSON-RPC 2.0 success response.
  82→ */
  83→export interface JsonRpcSuccessResponse<TResult = unknown> {
  84→  readonly jsonrpc: typeof JSONRPC_VERSION;
  85→  /** Echoed request identifier. */
  86→  readonly id: JsonRpcId;
  87→  /** The method return value. */
  88→  readonly result: TResult;
  89→  readonly error?: never;
  90→}
  91→
  92→/**
  93→ * A JSON-RPC 2.0 error object embedded in an error response.
  94→ */
  95→export interface JsonRpcError<TData = unknown> {
  96→  /** Machine-readable error code. */
  97→  readonly code: number;
  98→  /** Human-readable error message. */
  99→  readonly message: string;
 100→  /** Optional structured error data. */
 101→  readonly data?: TData;
 102→}
 103→
 104→/**
 105→ * A JSON-RPC 2.0 error response.
 106→ */
 107→export interface JsonRpcErrorResponse<TData = unknown> {
 108→  readonly jsonrpc: typeof JSONRPC_VERSION;
 109→  /** Echoed request identifier. */
 110→  readonly id: JsonRpcId | null;
 111→  readonly result?: never;
 112→  /** The error object. */
 113→  readonly error: JsonRpcError<TData>;
 114→}
 115→
 116→/**
 117→ * A JSON-RPC 2.0 response — either success or error.
 118→ */
 119→export type JsonRpcResponse<TResult = unknown, TData = unknown> =
 120→  | JsonRpcSuccessResponse<TResult>
 121→  | JsonRpcErrorResponse<TData>;
 122→
 123→/**
 124→ * A JSON-RPC 2.0 notification (a request with no `id`).
 125→ *
 126→ * Notifications are fire-and-forget — no response is expected.
 127→ */
 128→export interface JsonRpcNotification<
 129→  TMethod extends string = string,
 130→  TParams = unknown,
 131→> {
 132→  readonly jsonrpc: typeof JSONRPC_VERSION;
 133→  readonly id?: never;
 134→  /** The notification method name. */
 135→  readonly method: TMethod;
 136→  /** Structured parameters for the notification. */
 137→  readonly params: TParams;
 138→}
 139→
 140→/**
 141→ * Any well-formed JSON-RPC 2.0 message (request, response, or notification).
 142→ */
 143→export type JsonRpcMessage =
 144→  | JsonRpcRequest
 145→  | JsonRpcResponse
 146→  | JsonRpcNotification;
 147→
 148→// ---------------------------------------------------------------------------
 149→// Error Codes
 150→// ---------------------------------------------------------------------------
 151→
 152→/**
 153→ * Standard JSON-RPC 2.0 error codes.
 154→ *
 155→ * @see https://www.jsonrpc.org/specification#error_object
 156→ */
 157→export const JSONRPC_ERROR_CODES = {
 158→  /** Invalid JSON was received by the server. */
 159→  PARSE_ERROR: -32700,
 160→  /** The JSON sent is not a valid Request object. */
 161→  INVALID_REQUEST: -32600,
 162→  /** The method does not exist or is not available. */
 163→  METHOD_NOT_FOUND: -32601,
 164→  /** Invalid method parameter(s). */
 165→  INVALID_PARAMS: -32602,
 166→  /** Internal JSON-RPC error. */
 167→  INTERNAL_ERROR: -32603,
 168→} as const;
 169→
 170→export type JsonRpcErrorCode =
 171→  (typeof JSONRPC_ERROR_CODES)[keyof typeof JSONRPC_ERROR_CODES];
 172→
 173→/**
 174→ * Paperclip plugin-specific error codes.
 175→ *
 176→ * These live in the JSON-RPC "server error" reserved range (-32000 to -32099)
 177→ * as specified by JSON-RPC 2.0 for implementation-defined server errors.
 178→ *
 179→ * @see PLUGIN_SPEC.md §19.7 — Error Propagation Through The Bridge
 180→ */
 181→export const PLUGIN_RPC_ERROR_CODES = {
 182→  /** The worker process is not running or not reachable. */
 183→  WORKER_UNAVAILABLE: -32000,
 184→  /** The plugin does not have the required capability for this operation. */
 185→  CAPABILITY_DENIED: -32001,
 186→  /** The worker reported an unhandled error during method execution. */
 187→  WORKER_ERROR: -32002,
 188→  /** The method call timed out waiting for the worker response. */
 189→  TIMEOUT: -32003,
 190→  /** The worker does not implement the requested optional method. */
 191→  METHOD_NOT_IMPLEMENTED: -32004,
 192→  /** A catch-all for errors that do not fit other categories. */
 193→  UNKNOWN: -32099,
 194→} as const;
 195→
 196→export type PluginRpcErrorCode =
 197→  (typeof PLUGIN_RPC_ERROR_CODES)[keyof typeof PLUGIN_RPC_ERROR_CODES];
 198→
 199→// ---------------------------------------------------------------------------
 200→// Host → Worker Method Signatures (§13 Host-Worker Protocol)
 201→// ---------------------------------------------------------------------------
 202→
 203→/**
 204→ * Input for the `initialize` RPC method.
 205→ *
 206→ * @see PLUGIN_SPEC.md §13.1 — `initialize`
 207→ */
 208→export interface InitializeParams {
 209→  /** Full plugin manifest snapshot. */
 210→  manifest: PaperclipPluginManifestV1;
 211→  /** Resolved operator configuration (validated against `instanceConfigSchema`). */
 212→  config: Record<string, unknown>;
 213→  /** Instance-level metadata. */
 214→  instanceInfo: {
 215→    /** UUID of this Paperclip instance. */
 216→    instanceId: string;
 217→    /** Semver version of the running Paperclip host. */
 218→    hostVersion: string;
 219→  };
 220→  /** Host API version. */
 221→  apiVersion: number;
 222→}
 223→
 224→/**
 225→ * Result returned by the `initialize` RPC method.
 226→ */
 227→export interface InitializeResult {
 228→  /** Whether initialization succeeded. */
 229→  ok: boolean;
 230→  /** Optional methods the worker has implemented (e.g. "validateConfig", "onEvent"). */
 231→  supportedMethods?: string[];
 232→}
 233→
 234→/**
 235→ * Input for the `configChanged` RPC method.
 236→ *
 237→ * @see PLUGIN_SPEC.md §13.4 — `configChanged`
 238→ */
 239→export interface ConfigChangedParams {
 240→  /** The newly resolved configuration. */
 241→  config: Record<string, unknown>;
 242→}
 243→
 244→/**
 245→ * Input for the `validateConfig` RPC method.
 246→ *
 247→ * @see PLUGIN_SPEC.md §13.3 — `validateConfig`
 248→ */
 249→export interface ValidateConfigParams {
 250→  /** The configuration to validate. */
 251→  config: Record<string, unknown>;
 252→}
 253→
 254→/**
 255→ * Input for the `onEvent` RPC method.
 256→ *
 257→ * @see PLUGIN_SPEC.md §13.5 — `onEvent`
 258→ */
 259→export interface OnEventParams {
 260→  /** The domain event to deliver. */
 261→  event: PluginEvent;
 262→}
 263→
 264→/**
 265→ * Input for the `runJob` RPC method.
 266→ *
 267→ * @see PLUGIN_SPEC.md §13.6 — `runJob`
 268→ */
 269→export interface RunJobParams {
 270→  /** Job execution context. */
 271→  job: PluginJobContext;
 272→}
 273→
 274→/**
 275→ * Input for the `getData` RPC method.
 276→ *
 277→ * @see PLUGIN_SPEC.md §13.8 — `getData`
 278→ */
 279→export interface GetDataParams {
 280→  /** Plugin-defined data key (e.g. `"sync-health"`). */
 281→  key: string;
 282→  /** Context and query parameters from the UI. */
 283→  params: Record<string, unknown>;
 284→  /** Optional launcher/container metadata from the host render environment. */
 285→  renderEnvironment?: PluginLauncherRenderContextSnapshot | null;
 286→}
 287→
 288→/**
 289→ * Input for the `performAction` RPC method.
 290→ *
 291→ * @see PLUGIN_SPEC.md §13.9 — `performAction`
 292→ */
 293→export interface PerformActionParams {
 294→  /** Plugin-defined action key (e.g. `"resync"`). */
 295→  key: string;
 296→  /** Action parameters from the UI. */
 297→  params: Record<string, unknown>;
 298→  /** Optional launcher/container metadata from the host render environment. */
 299→  renderEnvironment?: PluginLauncherRenderContextSnapshot | null;
 300→}
 301→
 302→/**
 303→ * Input for the `executeTool` RPC method.
 304→ *
 305→ * @see PLUGIN_SPEC.md §13.10 — `executeTool`
 306→ */
 307→export interface ExecuteToolParams {
 308→  /** Tool name (without plugin namespace prefix). */
 309→  toolName: string;
 310→  /** Parsed parameters matching the tool's declared schema. */
 311→  parameters: unknown;
 312→  /** Agent run context. */
 313→  runContext: ToolRunContext;
 314→}
 315→
 316→// ---------------------------------------------------------------------------
 317→// UI launcher / modal host interaction payloads
 318→// ---------------------------------------------------------------------------
 319→
 320→/**
 321→ * Bounds request issued by a plugin UI running inside a host-managed launcher
 322→ * container such as a modal, drawer, or popover.
 323→ */
 324→export interface PluginModalBoundsRequest {
 325→  /** High-level size preset requested from the host. */
 326→  bounds: PluginLauncherBounds;
 327→  /** Optional explicit width override in CSS pixels. */
 328→  width?: number;
 329→  /** Optional explicit height override in CSS pixels. */
 330→  height?: number;
 331→  /** Optional lower bounds for host resizing decisions. */
 332→  minWidth?: number;
 333→  minHeight?: number;
 334→  /** Optional upper bounds for host resizing decisions. */
 335→  maxWidth?: number;
 336→  maxHeight?: number;
 337→}
 338→
 339→/**
 340→ * Reason metadata supplied by host-managed close lifecycle callbacks.
 341→ */
 342→export interface PluginRenderCloseEvent {
 343→  reason:
 344→    | "escapeKey"
 345→    | "backdrop"
 346→    | "hostNavigation"
 347→    | "programmatic"
 348→    | "submit"
 349→    | "unknown";
 350→  nativeEvent?: unknown;
 351→}
 352→
 353→/**
 354→ * Map of host→worker RPC method names to their `[params, result]` types.
 355→ *
 356→ * This type is the single source of truth for all methods the host can call
 357→ * on a worker. Used by both the host dispatcher and the worker handler to
 358→ * ensure type safety across the IPC boundary.
 359→ */
 360→export interface HostToWorkerMethods {
 361→  /** @see PLUGIN_SPEC.md §13.1 */
 362→  initialize: [params: InitializeParams, result: InitializeResult];
 363→  /** @see PLUGIN_SPEC.md §13.2 */
 364→  health: [params: Record<string, never>, result: PluginHealthDiagnostics];
 365→  /** @see PLUGIN_SPEC.md §12.5 */
 366→  shutdown: [params: Record<string, never>, result: void];
 367→  /** @see PLUGIN_SPEC.md §13.3 */
 368→  validateConfig: [params: ValidateConfigParams, result: PluginConfigValidationResult];
 369→  /** @see PLUGIN_SPEC.md §13.4 */
 370→  configChanged: [params: ConfigChangedParams, result: void];
 371→  /** @see PLUGIN_SPEC.md §13.5 */
 372→  onEvent: [params: OnEventParams, result: void];
 373→  /** @see PLUGIN_SPEC.md §13.6 */
 374→  runJob: [params: RunJobParams, result: void];
 375→  /** @see PLUGIN_SPEC.md §13.7 */
 376→  handleWebhook: [params: PluginWebhookInput, result: void];
 377→  /** @see PLUGIN_SPEC.md §13.8 */
 378→  getData: [params: GetDataParams, result: unknown];
 379→  /** @see PLUGIN_SPEC.md §13.9 */
 380→  performAction: [params: PerformActionParams, result: unknown];
 381→  /** @see PLUGIN_SPEC.md §13.10 */
 382→  executeTool: [params: ExecuteToolParams, result: ToolResult];
 383→}
 384→
 385→/** Union of all host→worker method names. */
 386→export type HostToWorkerMethodName = keyof HostToWorkerMethods;
 387→
 388→/** Required methods the worker MUST implement. */
 389→export const HOST_TO_WORKER_REQUIRED_METHODS: readonly HostToWorkerMethodName[] = [
 390→  "initialize",
 391→  "health",
 392→  "shutdown",
 393→] as const;
 394→
 395→/** Optional methods the worker MAY implement. */
 396→export const HOST_TO_WORKER_OPTIONAL_METHODS: readonly HostToWorkerMethodName[] = [
 397→  "validateConfig",
 398→  "configChanged",
 399→  "onEvent",
 400→  "runJob",
 401→  "handleWebhook",
 402→  "getData",
 403→  "performAction",
 404→  "executeTool",
 405→] as const;
 406→
 407→// ---------------------------------------------------------------------------
 408→// Worker → Host Method Signatures (SDK client calls)
 409→// ---------------------------------------------------------------------------
 410→
 411→/**
 412→ * Map of worker→host RPC method names to their `[params, result]` types.
 413→ *
 414→ * These represent the SDK client calls that the worker makes back to the
 415→ * host to access platform services (state, entities, config, etc.).
 416→ */
 417→export interface WorkerToHostMethods {
 418→  // Config
 419→  "config.get": [params: Record<string, never>, result: Record<string, unknown>];
 420→
 421→  // State
 422→  "state.get": [
 423→    params: { scopeKind: string; scopeId?: string; namespace?: string; stateKey: string },
 424→    result: unknown,
 425→  ];
 426→  "state.set": [
 427→    params: { scopeKind: string; scopeId?: string; namespace?: string; stateKey: string; value: unknown },
 428→    result: void,
 429→  ];
 430→  "state.delete": [
 431→    params: { scopeKind: string; scopeId?: string; namespace?: string; stateKey: string },
 432→    result: void,
 433→  ];
 434→
 435→  // Entities
 436→  "entities.upsert": [
 437→    params: {
 438→      entityType: string;
 439→      scopeKind: PluginStateScopeKind;
 440→      scopeId?: string;
 441→      externalId?: string;
 442→      title?: string;
 443→      status?: string;
 444→      data: Record<string, unknown>;
 445→    },
 446→    result: {
 447→      id: string;
 448→      entityType: string;
 449→      scopeKind: PluginStateScopeKind;
 450→      scopeId: string | null;
 451→      externalId: string | null;
 452→      title: string | null;
 453→      status: string | null;
 454→      data: Record<string, unknown>;
 455→      createdAt: string;
 456→      updatedAt: string;
 457→    },
 458→  ];
 459→  "entities.list": [
 460→    params: {
 461→      entityType?: string;
 462→      scopeKind?: PluginStateScopeKind;
 463→      scopeId?: string;
 464→      externalId?: string;
 465→      limit?: number;
 466→      offset?: number;
 467→    },
 468→    result: Array<{
 469→      id: string;
 470→      entityType: string;
 471→      scopeKind: PluginStateScopeKind;
 472→      scopeId: string | null;
 473→      externalId: string | null;
 474→      title: string | null;
 475→      status: string | null;
 476→      data: Record<string, unknown>;
 477→      createdAt: string;
 478→      updatedAt: string;
 479→    }>,
 480→  ];
 481→
 482→  // Events
 483→  "events.emit": [
 484→    params: { name: string; companyId: string; payload: unknown },
 485→    result: void,
 486→  ];
 487→  "events.subscribe": [
 488→    params: { eventPattern: string; filter?: Record<string, unknown> | null },
 489→    result: void,
 490→  ];
 491→
 492→  // HTTP
 493→  "http.fetch": [
 494→    params: { url: string; init?: Record<string, unknown> },
 495→    result: { status: number; statusText: string; headers: Record<string, string>; body: string },
 496→  ];
 497→
 498→  // Secrets
 499→  "secrets.resolve": [
 500→    params: { secretRef: string },
 501→    result: string,
 502→  ];
 503→
 504→  // Activity
 505→  "activity.log": [
 506→    params: {
 507→      companyId: string;
 508→      message: string;
 509→      entityType?: string;
 510→      entityId?: string;
 511→      metadata?: Record<string, unknown>;
 512→    },
 513→    result: void,
 514→  ];
 515→
 516→  // Metrics
 517→  "metrics.write": [
 518→    params: { name: string; value: number; tags?: Record<string, string> },
 519→    result: void,
 520→  ];
 521→
 522→  // Logger
 523→  "log": [
 524→    params: { level: "info" | "warn" | "error" | "debug"; message: string; meta?: Record<string, unknown> },
 525→    result: void,
 526→  ];
 527→
 528→  // Companies (read)
 529→  "companies.list": [
 530→    params: { limit?: number; offset?: number },
 531→    result: Company[],
 532→  ];
 533→  "companies.get": [
 534→    params: { companyId: string },
 535→    result: Company | null,
 536→  ];
 537→
 538→  // Projects (read)
 539→  "projects.list": [
 540→    params: { companyId: string; limit?: number; offset?: number },
 541→    result: Project[],
 542→  ];
 543→  "projects.get": [
 544→    params: { projectId: string; companyId: string },
 545→    result: Project | null,
 546→  ];
 547→  "projects.listWorkspaces": [
 548→    params: { projectId: string; companyId: string },
