 550→  ];
 551→  "projects.getPrimaryWorkspace": [
 552→    params: { projectId: string; companyId: string },
 553→    result: PluginWorkspace | null,
 554→  ];
 555→  "projects.getWorkspaceForIssue": [
 556→    params: { issueId: string; companyId: string },
 557→    result: PluginWorkspace | null,
 558→  ];
 559→
 560→  // Issues
 561→  "issues.list": [
 562→    params: {
 563→      companyId: string;
 564→      projectId?: string;
 565→      assigneeAgentId?: string;
 566→      status?: string;
 567→      limit?: number;
 568→      offset?: number;
 569→    },
 570→    result: Issue[],
 571→  ];
 572→  "issues.get": [
 573→    params: { issueId: string; companyId: string },
 574→    result: Issue | null,
 575→  ];
 576→  "issues.create": [
 577→    params: {
 578→      companyId: string;
 579→      projectId?: string;
 580→      goalId?: string;
 581→      parentId?: string;
 582→      title: string;
 583→      description?: string;
 584→      priority?: string;
 585→      assigneeAgentId?: string;
 586→    },
 587→    result: Issue,
 588→  ];
 589→  "issues.update": [
 590→    params: {
 591→      issueId: string;
 592→      patch: Record<string, unknown>;
 593→      companyId: string;
 594→    },
 595→    result: Issue,
 596→  ];
 597→  "issues.listComments": [
 598→    params: { issueId: string; companyId: string },
 599→    result: IssueComment[],
 600→  ];
 601→  "issues.createComment": [
 602→    params: { issueId: string; body: string; companyId: string },
 603→    result: IssueComment,
 604→  ];
 605→
 606→  // Issue Documents
 607→  "issues.documents.list": [
 608→    params: { issueId: string; companyId: string },
 609→    result: IssueDocumentSummary[],
 610→  ];
 611→  "issues.documents.get": [
 612→    params: { issueId: string; key: string; companyId: string },
 613→    result: IssueDocument | null,
 614→  ];
 615→  "issues.documents.upsert": [
 616→    params: {
 617→      issueId: string;
 618→      key: string;
 619→      body: string;
 620→      companyId: string;
