 705→/** Union of all worker→host method names. */
 706→export type WorkerToHostMethodName = keyof WorkerToHostMethods;
 707→
 708→// ---------------------------------------------------------------------------
 709→// Worker→Host Notification Types (fire-and-forget, no response)
 710→// ---------------------------------------------------------------------------
 711→
 712→/**
 713→ * Typed parameter shapes for worker→host JSON-RPC notifications.
 714→ *
 715→ * Notifications are fire-and-forget — the worker does not wait for a response.
 716→ * These are used for streaming events and logging, not for request-response RPCs.
 717→ */
 718→export interface WorkerToHostNotifications {
 719→  /**
 720→   * Forward a stream event to connected SSE clients.
 721→   *
 722→   * Emitted by the worker for each event on a stream channel. The host
 723→   * publishes to the PluginStreamBus, which fans out to all SSE clients
 724→   * subscribed to the (pluginId, channel, companyId) tuple.
 725→   *
 726→   * The `event` payload is JSON-serializable and sent as SSE `data:`.
 727→   * The default SSE event type is `"message"`.
 728→   */
 729→  "streams.emit": {
 730→    channel: string;
 731→    companyId: string;
 732→    event: unknown;
 733→  };
 734→
 735→  /**
 736→   * Signal that a stream channel has been opened.
 737→   *
 738→   * Emitted when the worker calls `ctx.streams.open(channel, companyId)`.
 739→   * UI clients may use this to display a "connected" indicator or begin
 740→   * buffering input. The host tracks open channels so it can emit synthetic
 741→   * close events if the worker crashes.
 742→   */
 743→  "streams.open": {
 744→    channel: string;
 745→    companyId: string;
 746→  };
 747→
 748→  /**
 749→   * Signal that a stream channel has been closed.
 750→   *
 751→   * Emitted when the worker calls `ctx.streams.close(channel)`, or
 752→   * synthetically by the host when a worker process exits with channels
 753→   * still open. UI clients should treat this as terminal and disconnect
 754→   * the SSE connection.
 755→   */
 756→  "streams.close": {
 757→    channel: string;
 758→    companyId: string;
 759→  };
 760→}
 761→
 762→/** Union of all worker→host notification method names. */
 763→export type WorkerToHostNotificationName = keyof WorkerToHostNotifications;
 764→
 765→// ---------------------------------------------------------------------------
 766→// Typed Request / Response Helpers
 767→// ---------------------------------------------------------------------------
 768→
 769→/**
 770→ * A typed JSON-RPC request for a specific host→worker method.
 771→ */
 772→export type HostToWorkerRequest<M extends HostToWorkerMethodName> =
 773→  JsonRpcRequest<M, HostToWorkerMethods[M][0]>;
 774→
 775→/**
 776→ * A typed JSON-RPC success response for a specific host→worker method.
 777→ */
 778→export type HostToWorkerResponse<M extends HostToWorkerMethodName> =
 779→  JsonRpcSuccessResponse<HostToWorkerMethods[M][1]>;
 780→
 781→/**
 782→ * A typed JSON-RPC request for a specific worker→host method.
 783→ */
 784→export type WorkerToHostRequest<M extends WorkerToHostMethodName> =
 785→  JsonRpcRequest<M, WorkerToHostMethods[M][0]>;
 786→
 787→/**
 788→ * A typed JSON-RPC success response for a specific worker→host method.
 789→ */
 790→export type WorkerToHostResponse<M extends WorkerToHostMethodName> =
 791→  JsonRpcSuccessResponse<WorkerToHostMethods[M][1]>;
 792→
 793→// ---------------------------------------------------------------------------
 794→// Message Factory Functions
 795→// ---------------------------------------------------------------------------
 796→
 797→/** Counter for generating unique request IDs when no explicit ID is provided. */
 798→let _nextId = 1;
 799→
 800→/** Wrap around before reaching Number.MAX_SAFE_INTEGER to prevent precision loss. */
 801→const MAX_SAFE_RPC_ID = Number.MAX_SAFE_INTEGER - 1;
 802→
 803→/**
 804→ * Create a JSON-RPC 2.0 request message.
 805→ *
 806→ * @param method - The RPC method name
 807→ * @param params - Structured parameters
 808→ * @param id - Optional explicit request ID (auto-generated if omitted)
 809→ */
 810→export function createRequest<TMethod extends string>(
 811→  method: TMethod,
 812→  params: unknown,
 813→  id?: JsonRpcId,
 814→): JsonRpcRequest<TMethod> {
 815→  if (_nextId >= MAX_SAFE_RPC_ID) {
 816→    _nextId = 1;
 817→  }
 818→  return {
 819→    jsonrpc: JSONRPC_VERSION,
 820→    id: id ?? _nextId++,
 821→    method,
 822→    params,
 823→  };
 824→}
 825→
 826→/**
 827→ * Create a JSON-RPC 2.0 success response.
 828→ *
 829→ * @param id - The request ID being responded to
 830→ * @param result - The result value
 831→ */
 832→export function createSuccessResponse<TResult>(
 833→  id: JsonRpcId,
 834→  result: TResult,
 835→): JsonRpcSuccessResponse<TResult> {
 836→  return {
 837→    jsonrpc: JSONRPC_VERSION,
 838→    id,
 839→    result,
 840→  };
 841→}
 842→
 843→/**
 844→ * Create a JSON-RPC 2.0 error response.
 845→ *
 846→ * @param id - The request ID being responded to (null if the request ID could not be determined)
 847→ * @param code - Machine-readable error code
 848→ * @param message - Human-readable error message
 849→ * @param data - Optional structured error data
 850→ */
 851→export function createErrorResponse<TData = unknown>(
 852→  id: JsonRpcId | null,
 853→  code: number,
 854→  message: string,
 855→  data?: TData,
 856→): JsonRpcErrorResponse<TData> {
 857→  const response: JsonRpcErrorResponse<TData> = {
 858→    jsonrpc: JSONRPC_VERSION,
 859→    id,
 860→    error: data !== undefined
 861→      ? { code, message, data }
 862→      : { code, message } as JsonRpcError<TData>,
 863→  };
 864→  return response;
 865→}
 866→
 867→/**
 868→ * Create a JSON-RPC 2.0 notification (fire-and-forget, no response expected).
 869→ *
 870→ * @param method - The notification method name
 871→ * @param params - Structured parameters
 872→ */
 873→export function createNotification<TMethod extends string>(
 874→  method: TMethod,
 875→  params: unknown,
 876→): JsonRpcNotification<TMethod> {
 877→  return {
 878→    jsonrpc: JSONRPC_VERSION,
 879→    method,
 880→    params,
 881→  };
 882→}
 883→
 884→// ---------------------------------------------------------------------------
 885→// Type Guards
 886→// ---------------------------------------------------------------------------
 887→
 888→/**
 889→ * Check whether a value is a well-formed JSON-RPC 2.0 request.
 890→ *
 891→ * A request has `jsonrpc: "2.0"`, a string `method`, and an `id`.
 892→ */
 893→export function isJsonRpcRequest(value: unknown): value is JsonRpcRequest {
 894→  if (typeof value !== "object" || value === null) return false;
 895→  const obj = value as Record<string, unknown>;
 896→  return (
 897→    obj.jsonrpc === JSONRPC_VERSION &&
 898→    typeof obj.method === "string" &&
 899→    "id" in obj &&
 900→    obj.id !== undefined &&
 901→    obj.id !== null
 902→  );
 903→}
 904→
 905→/**
 906→ * Check whether a value is a well-formed JSON-RPC 2.0 notification.
 907→ *
 908→ * A notification has `jsonrpc: "2.0"`, a string `method`, but no `id`.
 909→ */
 910→export function isJsonRpcNotification(
 911→  value: unknown,
 912→): value is JsonRpcNotification {
 913→  if (typeof value !== "object" || value === null) return false;
 914→  const obj = value as Record<string, unknown>;
 915→  return (
 916→    obj.jsonrpc === JSONRPC_VERSION &&
 917→    typeof obj.method === "string" &&
 918→    !("id" in obj)
 919→  );
 920→}
 921→
 922→/**
 923→ * Check whether a value is a well-formed JSON-RPC 2.0 response (success or error).
 924→ */
 925→export function isJsonRpcResponse(value: unknown): value is JsonRpcResponse {
 926→  if (typeof value !== "object" || value === null) return false;
 927→  const obj = value as Record<string, unknown>;
 928→  return (
 929→    obj.jsonrpc === JSONRPC_VERSION &&
 930→    "id" in obj &&
 931→    ("result" in obj || "error" in obj)
 932→  );
 933→}
 934→
 935→/**
 936→ * Check whether a JSON-RPC response is a success response.
 937→ */
 938→export function isJsonRpcSuccessResponse(
 939→  response: JsonRpcResponse,
 940→): response is JsonRpcSuccessResponse {
 941→  return "result" in response && !("error" in response && response.error !== undefined);
 942→}
 943→
 944→/**
 945→ * Check whether a JSON-RPC response is an error response.
 946→ */
 947→export function isJsonRpcErrorResponse(
 948→  response: JsonRpcResponse,
 949→): response is JsonRpcErrorResponse {
 950→  return "error" in response && response.error !== undefined;
 951→}
 952→
 953→// ---------------------------------------------------------------------------
 954→// Serialization Helpers
 955→// ---------------------------------------------------------------------------
 956→
 957→/**
 958→ * Line delimiter for JSON-RPC messages over stdio.
 959→ *
 960→ * Each message is a single line of JSON terminated by a newline character.
 961→ * This follows the newline-delimited JSON (NDJSON) convention.
 962→ */
 963→export const MESSAGE_DELIMITER = "\n" as const;
 964→
 965→/**
 966→ * Serialize a JSON-RPC message to a newline-delimited string for transmission
 967→ * over stdio.
 968→ *
 969→ * @param message - Any JSON-RPC message (request, response, or notification)
 970→ * @returns The JSON string terminated with a newline
 971→ */
 972→export function serializeMessage(message: JsonRpcMessage): string {
 973→  return JSON.stringify(message) + MESSAGE_DELIMITER;
 974→}
 975→
 976→/**
 977→ * Parse a JSON string into a JSON-RPC message.
 978→ *
 979→ * Returns the parsed message or throws a `JsonRpcParseError` if the input
 980→ * is not valid JSON or does not conform to the JSON-RPC 2.0 structure.
 981→ *
 982→ * @param line - A single line of JSON text (with or without trailing newline)
 983→ * @returns The parsed JSON-RPC message
 984→ * @throws {JsonRpcParseError} If parsing fails
 985→ */
 986→export function parseMessage(line: string): JsonRpcMessage {
 987→  const trimmed = line.trim();
 988→  if (trimmed.length === 0) {
 989→    throw new JsonRpcParseError("Empty message");
 990→  }
 991→
 992→  let parsed: unknown;
 993→  try {
 994→    parsed = JSON.parse(trimmed);
 995→  } catch {
 996→    throw new JsonRpcParseError(`Invalid JSON: ${trimmed.slice(0, 200)}`);
 997→  }
 998→
 999→  if (typeof parsed !== "object" || parsed === null) {
1000→    throw new JsonRpcParseError("Message must be a JSON object");
1001→  }
1002→
1003→  const obj = parsed as Record<string, unknown>;
1004→
1005→  if (obj.jsonrpc !== JSONRPC_VERSION) {
1006→    throw new JsonRpcParseError(
1007→      `Invalid or missing jsonrpc version (expected "${JSONRPC_VERSION}", got ${JSON.stringify(obj.jsonrpc)})`,
1008→    );
1009→  }
1010→
1011→  // It's a valid JSON-RPC 2.0 envelope — return as-is and let the caller
1012→  // use the type guards for more specific classification.
1013→  return parsed as JsonRpcMessage;
1014→}
1015→
1016→// ---------------------------------------------------------------------------
1017→// Error Classes
1018→// ---------------------------------------------------------------------------
1019→
1020→/**
1021→ * Error thrown when a JSON-RPC message cannot be parsed.
1022→ */
1023→export class JsonRpcParseError extends Error {
1024→  override readonly name = "JsonRpcParseError";
1025→  constructor(message: string) {
1026→    super(message);
1027→  }
1028→}
1029→
1030→/**
1031→ * Error thrown when a JSON-RPC call fails with a structured error response.
1032→ *
1033→ * Captures the full `JsonRpcError` so callers can inspect the code and data.
1034→ */
1035→export class JsonRpcCallError extends Error {
1036→  override readonly name = "JsonRpcCallError";
1037→  /** The JSON-RPC error code. */
1038→  readonly code: number;
1039→  /** Optional structured error data from the response. */
1040→  readonly data: unknown;
1041→
1042→  constructor(error: JsonRpcError) {
1043→    super(error.message);
1044→    this.code = error.code;
1045→    this.data = error.data;
1046→  }
1047→}
1048→
1049→// ---------------------------------------------------------------------------
1050→// Reset helper (testing only)
1051→// ---------------------------------------------------------------------------
1052→
1053→/**
1054→ * Reset the internal request ID counter. **For testing only.**
1055→ *
1056→ * @internal
1057→ */
1058→export function _resetIdCounter(): void {
1059→  _nextId = 1;
1060→}
